INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2016H2_GK', 'RK_SA_ARCH_2016H2_GK_Q007', '某文件系统文件存储采用文件索引节点法。假设文件索引节点中有8个地址项iaddr[0]～iaddr[7]，每个地址项大小为4字节，其中地址项iaddr[0]～iaddr[5]为直接地址索引，iaddr[6]是一级间接地址索引，iaddr[7]是二级间接地址索引，磁盘索引块和磁盘数据块大小均为4KB。该文件系统可表示的单个文件最大长度是（7）KB。若要访问iclsClient.dll文件的逻辑块号分别为6、520和1030，则系统应分别采用（8）。', 7, '单选题', '[{"key":"A","text":"1030","scores":{"score":0}},{"key":"B","text":"65796","scores":{"score":0}},{"key":"C","text":"1049606","scores":{"score":0}},{"key":"D","text":"4198424","scores":{"score":1}}]', '{"questionType":"单选题","sourceQuestionNo":7,"correctOptionKey":"D","explanation":"直接索引范围：6*4KB=24KB ，对应逻辑块号：0-5；\\n一级间接索引范围：(4KB/4B)*4KB=4096KB ，对应逻辑块号：6-1029；\\n二级间接索引范围：(4KB/4B)*(4KB/4B)*4KB=4194304KB ，对应逻辑块号：1030以及上。\\n24KB + 4096KB + 4194304KB = 4198424KB。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

