VALUES
    ('RK_SA_ARCH_2016H2_GK', 'RK_SA_ARCH_2016H2_GK_Q012', '假设某证券公司的股票交易系统中有正在运行的事务，此时，若要转储该交易系统数据库中的全部数据，则应采用（12）方式。', 12, '单选题', '[{"key":"A","text":"静态全局转储","scores":{"score":0}},{"key":"B","text":"动态全局转储","scores":{"score":1}},{"key":"C","text":"静态增量转储","scores":{"score":0}},{"key":"D","text":"动态增量转储","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":12,"correctOptionKey":"B","explanation":"从题目中“系统中有正在运行的事务”可知应采用动态方式，从题目中“全部数据”可知应是全局转储，所以应采用：动态全局转储。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
