INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2016H2_GK', 'RK_SA_ARCH_2016H2_GK_Q020', 'ERP（Enterprise Resource Planning）是建立在信息技术的基础上，利用现代企业的先进管理思想，对企业的物流、资金流和（20）流进行全面集成管理的管理信息系统，为企业提供决策、计划、控制与经营业绩评估的全方位和系统化的管理平台。在ERP系统中，（21）管理模块主要是对企业物料的进、出、存进行管理。', 20, '单选题', '[{"key":"A","text":"产品","scores":{"score":0}},{"key":"B","text":"人力资源","scores":{"score":0}},{"key":"C","text":"信息","scores":{"score":1}},{"key":"D","text":"加工","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":20,"correctOptionKey":"C","explanation":"(20)本题考查到的，是信息化的“三流”：信息流，资金流，物流。\\n(21)采购与库存管理是ERP的基本模块，其中采购管理模块是对采购工作——从采购订单产生至货物收到的全过程进行组织、实施与控制，库存管理（Inventory Management，IM）模块则是对企业物料的进、出、存进行管理。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

