    ('RK_SA_ARCH_2016H2_GK', 'RK_SA_ARCH_2016H2_GK_Q066', '软件著作权保护的对象不包括（66）。', 66, '单选题', '[{"key":"A","text":"源程序","scores":{"score":0}},{"key":"B","text":"目标程序","scores":{"score":0}},{"key":"C","text":"用户手册","scores":{"score":0}},{"key":"D","text":"处理过程","scores":{"score":1}}]', '{"questionType":"单选题","sourceQuestionNo":66,"correctOptionKey":"D","explanation":"软件著作权中规定：开发软件所用的思想、处理过程、操作方法或者数学概念不受保护。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
