                     extra_info = VALUES(extra_info);

INSERT INTO arelore_education.user_detection_question
(type_code, question_code, question_name, question_order, question_description, options, extra_info)
VALUES
    ('RK_SA_ARCH_2016H2_GK', 'RK_SA_ARCH_2016H2_GK_Q067', 'M公司购买了N画家创作的一幅美术作品原件。M公司未经N画家的许可，擅自将这幅美术作品作为商标注册，并大量复制用于该公司的产品上。M公司的行为侵犯了N画家的（67）。', 67, '单选题', '[{"key":"A","text":"著作权","scores":{"score":1}},{"key":"B","text":"发表权","scores":{"score":0}},{"key":"C","text":"商标权","scores":{"score":0}},{"key":"D","text":"展览权","scores":{"score":0}}]', '{"questionType":"单选题","sourceQuestionNo":67,"correctOptionKey":"A","explanation":"著作权法规定：美术作品的著作权不随原作品所有权的转变而发生变化。所以M公司购买N画家的美术作品，著作权不归M公司，而归N画家。M公司将美术作品注册为商标，是侵犯了N画家著作权的。","imageHashValues":[]}')
ON DUPLICATE KEY UPDATE
                     question_name = VALUES(question_name),
                     question_order = VALUES(question_order),
                     question_description = VALUES(question_description),
                     options = VALUES(options),
                     extra_info = VALUES(extra_info);

